  label: string;
  icon: LucideIcon;
  onSelect: () => void;
  /** Muted text at the item's right: the zone's city */
  detail?: string;
  /** Key that does the same, shown at the right */
  shortcut?: string;
  /** Drawn in red, after a separator */
  destructive?: boolean;
}

/**
 * Keeps clicks in a label and its menus from reaching the time grid, whose
 * own click clears the selected event
 */
function stopClick(e: React.MouseEvent) {
  e.stopPropagation();
}

/**
 * The zone list of a label's menu, with its search field: picks a zone for
 * "Change time zone" or the "+" button
 */
function TimeZoneMenuList({
  onSelect,
}: {
  onSelect: (timeZone: string) => void;
}) {
  const [query, setQuery] = React.useState("");
  return (
    <Command
      shouldFilter={false}
      label="Time zones"
      className="bg-transparent text-inherit"
    >
      {/* A plain input: the list filters itself, and arrow keys still
          reach the list's own handler */}
      <input
        autoFocus
        aria-label="Time zone"
        placeholder="Time zone"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        className={SEARCH_INPUT_CLASS}
      />
      <div className="max-h-[300px] overflow-y-auto" role="presentation">
        <TimeZoneList query={query} onSelect={onSelect} variant="menu" />
      </div>
    </Command>
  );
}

/**
 * The "+" that adds a time zone, as the left-most column, from a searchable
 * list, as Notion Calendar's. The time grid puts it in the "All-day"
 * corner, under the labels: a long label ("GMT+5:30") fills its column
 */
export function AddTimeZoneButton() {
  const { changeTimeZones } = useCalendar();
  const [open, setOpen] = React.useState(false);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label="Add time zone"
          title="Add time zone"
          className={cn(
            "absolute top-[7px] left-1.5 z-10 flex size-4 items-center justify-center rounded-sm text-muted-foreground hover:bg-accent hover:text-foreground",
            open && "bg-accent text-foreground",
          )}
        >
          <Plus className="size-3" />
        </button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className={cn("w-[360px] max-w-[calc(100vw-16px)]", MENU_CLASS)}
        onClick={stopClick}
        onKeyDown={(e) => {
          if (e.key !== "Escape") return;
          e.stopPropagation();
          setOpen(false);
        }}
      >
        {open && (
          <TimeZoneMenuList
            onSelect={(zone) => {
              setOpen(false);
              changeTimeZones((zones) => addTimeZone(zones, zone));
            }}
          />
        )}
      </PopoverContent>
    </Popover>
  );
}

/**
 * The label above one time zone column of the time grid ("EST", "GMT−3").
 * A click or right-click opens Notion Calendar's menu for it: "Change time
 * zone", "Make time zone primary" (or secondary) and "Remove time zone
 * from list". The zone the calendar travelled to is filled in the primary
 * color, with "Add as primary time zone", "Add as secondary time zone" and
 * "Travel back home" instead, and an x that travels back home.
 */
export function TimeZoneAxisLabel({
  column,
  hasOtherZones,
}: TimeZoneAxisLabelProps) {
  const { changeTimeZones, travelToTimeZone } = useCalendar();
  const [open, setOpen] = React.useState(false);
  /** "Change time zone" swaps the menu for a zone list */
  const [isChanging, setIsChanging] = React.useState(false);
  const { timeZone, label, kind } = column;
  const city = getTimeZoneCity(timeZone) || timeZone;
  const isTravel = kind === "travel";
  const isPrimary = kind === "primary" || kind === "home";

  const handleOpenChange = (next: boolean) => {
    setOpen(next);
    if (next) setIsChanging(false);
  };

  /** Closes the menu, then runs the item's action */
  const run = (action: () => void) => () => {
    setOpen(false);
    action();
  };

  const items: LabelMenuItem[] = isTravel
    ? [
        {
          label: "Add as primary time zone",
          icon: Plus,
          onSelect: run(() => {
            changeTimeZones((zones) => makeTimeZonePrimary(zones, timeZone));
            travelToTimeZone(null);
          }),
        },
        {
          label: "Add as secondary time zone",
          icon: Plus,
          onSelect: run(() => {
            changeTimeZones((zones) => addTimeZone(zones, timeZone));
            travelToTimeZone(null);
          }),
        },
        {
          label: "Travel back home",
          icon: X,
          shortcut: "esc",
          destructive: true,
          onSelect: run(() => travelToTimeZone(null)),
        },
      ]
    : [
        {
          label: "Change time zone",
          icon: Globe,
          detail: city,
          onSelect: () => setIsChanging(true),
        },
        ...(isPrimary
          ? hasOtherZones
            ? [
                {
                  label: "Make time zone secondary",
                  icon: ArrowLeft,
                  onSelect: run(() => changeTimeZones(makeTimeZoneSecondary)),
                },
              ]
            : []
          : [
              {
                label: "Make time zone primary",
                icon: ArrowRight,
                onSelect: run(() =>
                  changeTimeZones((zones) =>
                    makeTimeZonePrimary(zones, timeZone),
                  ),
                ),
              },
            ]),
        // The only zone left stays
        ...(isPrimary && !hasOtherZones
          ? []
          : [
              {
                label: "Remove time zone from list",
                icon: X,
                destructive: true,
                onSelect: run(() =>
                  changeTimeZones((zones) => removeTimeZone(zones, timeZone)),
                ),
              },
            ]),
      ];
  const actions = items.filter((item) => !item.destructive);
  const destructive = items.filter((item) => item.destructive);

  const renderItem = (item: LabelMenuItem) => {
    const Icon = item.icon;
    return (
      <CommandItem
        key={item.label}
        value={item.label}
        onSelect={item.onSelect}
        className={cn(
          MENU_ITEM_CLASS,
          item.destructive && MENU_ITEM_DESTRUCTIVE_CLASS,
        )}
      >
        <Icon className="size-4 shrink-0" />
        <span className="min-w-0 flex-1 truncate">{item.label}</span>
        {item.detail && (
          <span className={cn("shrink-0", EVENT_DETAIL_MENU_SECONDARY_CLASS)}>
            {item.detail}
          </span>
        )}
        {item.shortcut && (
          <Kbd className="shrink-0 bg-white/10 text-[#8B8B8B]">
            {item.shortcut}
          </Kbd>
        )}
      </CommandItem>
    );
  };

  return (
    <div
      className={cn(
        "relative flex w-16 flex-shrink-0 items-center justify-end pr-1",
        isTravel
          ? "bg-primary text-primary-foreground"
          : "text-muted-foreground",
      )}
      onClick={stopClick}
    >
      {/* Empty on the server and during hydration, where zones are unknown */}
      {label && (
        <Popover open={open} onOpenChange={handleOpenChange}>
          <PopoverTrigger asChild>
            <button
              type="button"
              aria-label={`${label} ${city} time zone`}
              onContextMenu={(e) => {
                e.preventDefault();
                handleOpenChange(true);
              }}
              className={cn(
                // Its own size: next to a text color in one class list,
                // tailwind-merge would drop the custom `text-xxs`
                "rounded-sm px-1 py-0.5 text-xxs leading-none outline-none focus-visible:ring-1 focus-visible:ring-ring",
                isTravel ? "hover:bg-white/15" : "hover:bg-accent",
                open && !isTravel && "bg-accent",
              )}
            >
              {label}
            </button>
          </PopoverTrigger>
          <PopoverContent
            align="start"
            className={cn(
              isChanging ? "w-[360px] max-w-[calc(100vw-16px)]" : "w-[240px]",
              MENU_CLASS,
            )}
            onClick={stopClick}
            onKeyDown={(e) => {
              if (e.key !== "Escape") return;
              // The calendar's Escape would deselect, or travel back home
              e.stopPropagation();
              setOpen(false);
            }}
          >
            {isChanging ? (
              <TimeZoneMenuList
                onSelect={(zone) => {
                  setOpen(false);
                  changeTimeZones((zones) =>
                    replaceTimeZone(zones, timeZone, zone),
                  );
                }}
              />
            ) : (
              <Command
                label={`${label} time zone`}
                // Takes the focus when the menu opens, so the arrow keys
                // and Enter reach the items
                tabIndex={0}
                className="bg-transparent p-1.5 text-inherit outline-none"
              >
                <CommandGroup className="p-0">
                  {actions.map(renderItem)}
                </CommandGroup>
                {destructive.length > 0 && (
                  <>
                    <div className="mx-1 my-[5px] h-px bg-[#303030]" />
                    <CommandGroup className="p-0">
                      {destructive.map(renderItem)}
                    </CommandGroup>
                  </>
                )}
              </Command>
            )}
          </PopoverContent>
        </Popover>
      )}
      {isTravel && (
        // Tooltips need a provider with Radix; a closer one (yours) still wins
        <TooltipProvider>
          <Tooltip>
            <TooltipTrigger asChild>
              <button
                type="button"
                aria-label="Travel back home"
                onClick={() => travelToTimeZone(null)}
                className="absolute top-0.5 right-0.5 flex size-3 items-center justify-center rounded-full bg-primary text-primary-foreground ring-1 ring-primary-foreground/80"
              >
                <X className="size-2" strokeWidth={3} />
              </button>
            </TooltipTrigger>
            <TooltipContent side="bottom">
              Travel back home <Kbd className="ml-1">esc</Kbd>
            </TooltipContent>
          </Tooltip>
        </TooltipProvider>
      )}
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import {
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandSeparator,
} from "@/components/ui/command";
import {
  POPULAR_TIME_ZONES,
  getTimeZoneOption,
  getTimeZoneOptions,
  searchTimeZones,
} from "@/lib/time-zones";
import type {
  TimeZoneListProps,
  TimeZoneListVariant,
  TimeZoneOption,
} from "./week-view-types";

/** En dash between a zone's name and its city, as Notion Calendar writes it */
const NAME_CITY_SEPARATOR = " – ";

/** A titled run of zones in the list */
interface TimeZoneSection {
  key: string;
  /** Heading above the zones; none for the popular ones on top */
  heading?: string;
  options: TimeZoneOption[];
}

/** Classes of each list's items and muted text */
const VARIANT_CLASSES: Record<
  TimeZoneListVariant,
  { item: string; muted: string; heading: string; separator: string }
> = {
  command: {
    item: "",
    muted: "text-muted-foreground",
    heading: "",
    separator: "",
  },
  menu: {
    item: "h-[30px] gap-[9px] rounded-md py-0 pr-2 pl-1.5 text-sm text-[#D4D4D4] data-[selected=true]:bg-[#303030] data-[selected=true]:text-[#D4D4D4]",
    muted: "text-[#7F7F7F]",
    heading: "[&_[cmdk-group-heading]]:text-[#7F7F7F]",
    separator: "mx-0 bg-[#303030]",
  },
};

/**
 * The zones of a time zone picker, for Notion Calendar's "Travel to time
 * zone...", "Show additional time zones..." and the time axis labels'
 * menus. Renders cmdk groups: put it in a `Command` with
 * `shouldFilter={false}` next to the input that sets `query`. Without a
 * query it lists the popular zones, then every zone by offset under "All
 * time zones"; a query lists the zones whose offset, city, name or id
 * match it.
 */
export function TimeZoneList({
  query,
  onSelect,
  timeZones,
  variant = "command",
}: TimeZoneListProps) {
  // Offsets as of when the list opened
  const [now] = React.useState(() => new Date());
  // Every zone, listed once per mount: typing searches it
  const allOptions = React.useMemo(() => getTimeZoneOptions(now), [now]);
  const classes = VARIANT_CLASSES[variant];

  const sections = React.useMemo<TimeZoneSection[]>(() => {
    const byId = new Map(allOptions.map((option) => [option.id, option]));
    const pick = (ids: string[]) =>
      ids.map((id) => byId.get(id) ?? getTimeZoneOption(now, id));
    if (timeZones) {
      return [
        { key: "shown", options: searchTimeZones(pick(timeZones), query) },
      ];
    }
    if (query.trim()) {
      return [{ key: "search", options: searchTimeZones(allOptions, query) }];
    }
    return [
      { key: "popular", options: pick(POPULAR_TIME_ZONES) },
      { key: "all", heading: "All time zones", options: allOptions },
    ];
  }, [allOptions, now, timeZones, query]);

  return (
    <>
      <CommandEmpty className={cn("py-6 text-center text-sm", classes.muted)}>
        No time zones found.
      </CommandEmpty>
      {sections.map((section, index) => (
        <React.Fragment key={section.key}>
          {index > 0 && <CommandSeparator className={classes.separator} />}
          <CommandGroup
            heading={section.heading}
            className={cn(variant === "menu" && "p-1", classes.heading)}
          >
            {section.options.map((option) => (
              <CommandItem
                key={option.id}
                // Unique across sections: a popular zone is also under "All"
                value={`${section.key}:${option.id}`}
                onSelect={() => onSelect(option.id)}
                className={classes.item}
              >
                {variant === "command" ? (
                  <span className="min-w-0 truncate">
                    ({option.offsetLabel}) {option.name}
                    {NAME_CITY_SEPARATOR}
                    {option.city}
                  </span>
                ) : (
                  <>
                    <span className={cn("shrink-0", classes.muted)}>
                      {option.offsetLabel}
                    </span>
                    <span className="min-w-0 flex-1 truncate">
                      {option.name}
                      {NAME_CITY_SEPARATOR}
                      {option.city}
                    </span>
                  </>
                )}
              </CommandItem>
            ))}
          </CommandGroup>
        </React.Fragment>
      ))}
    </>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { addDays } from "date-fns";

import {
  isPrimaryPress,
  suppressNextClick,
  usePointerGesture,
} from "@/hooks/use-pointer-gesture";
import type {
  AllDayResizeState,
  CalendarEvent,
  PointerGestureStart,
} from "@/components/week-view-types";

interface UseAllDayResizeOptions {
  days: Date[];
  dayColumnWidth: number;
  allDayContainerRef: React.RefObject<HTMLDivElement | null>;
  events: CalendarEvent[];
  onEventChange?: (event: CalendarEvent) => void;
  onEventClick?: (event: CalendarEvent) => void;
}

interface UseAllDayResizeReturn {
  allDayResizeState: AllDayResizeState | null;
  handleAllDayResizePointerDown: (
    e: React.PointerEvent<HTMLElement>,
    event: CalendarEvent,
    edge: "left" | "right" | "move",
    startColumn: number,
    endColumn: number,
  ) => void;
}

const DRAG_THRESHOLD_PX = 4;

function clamp(value: number, min: number, max: number): number {
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

/** `day` at the time of day of `time` */
function atTimeOf(day: Date, time: Date): Date {
  const result = new Date(day);
  result.setHours(
    time.getHours(),
    time.getMinutes(),
    time.getSeconds(),
    time.getMilliseconds(),
  );
  return result;
}

interface ResizeInfo {
  eventId: string;
  event: CalendarEvent;
  /** Pointer driving the gesture; moves from other pointers are ignored */
  pointerId: number;
  /** "mouse", "pen" or "touch" */
  pointerType: string;
  edge: "left" | "right" | "move";
  startClientX: number;
  isResizing: boolean;
  originalStartColumn: number;
  originalEndColumn: number;
  /** Column index where the gesture started (used for move delta) */
  startColumnIndex: number;
  /** Offset from cursor to event left edge when the gesture started (px) */
  cursorOffsetX: number;
  /** Offset from cursor to event top edge when the gesture started (px) */
  cursorOffsetY: number;
  /** Latest start column, committed to the parent on pointerup */
  currentStartColumn: number;
  /** Latest end column, committed to the parent on pointerup */
  currentEndColumn: number;
}

export function useAllDayResize({
  days,
  dayColumnWidth,
  allDayContainerRef,
  events,
  onEventChange,
  onEventClick,
}: UseAllDayResizeOptions): UseAllDayResizeReturn {
  const [allDayResizeState, setAllDayResizeState] =
    useState<AllDayResizeState | null>(null);
  const { startGesture } = usePointerGesture({
    containerRef: allDayContainerRef,
  });

  const resizeRef = useRef<ResizeInfo | null>(null);
  const onEventChangeRef = useRef(onEventChange);
  const onEventClickRef = useRef(onEventClick);
  const eventsRef = useRef(events);
  const daysRef = useRef(days);
  const dayColumnWidthRef = useRef(dayColumnWidth);

  useEffect(() => {
    onEventChangeRef.current = onEventChange;
  }, [onEventChange]);
  useEffect(() => {
    onEventClickRef.current = onEventClick;
  }, [onEventClick]);
  useEffect(() => {
    eventsRef.current = events;
  }, [events]);
  useEffect(() => {
    daysRef.current = days;
  }, [days]);
  useEffect(() => {
    dayColumnWidthRef.current = dayColumnWidth;
  }, [dayColumnWidth]);

  const handlePointerMoveRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePointerUpRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePointerCancelRef = useRef<((e: PointerEvent) => void) | null>(
    null,
  );

  const cleanup = useCallback(() => {
    if (handlePointerMoveRef.current) {
      window.removeEventListener("pointermove", handlePointerMoveRef.current);
    }
    if (handlePointerUpRef.current) {
      window.removeEventListener("pointerup", handlePointerUpRef.current);
    }
    if (handlePointerCancelRef.current) {
      window.removeEventListener(
        "pointercancel",
        handlePointerCancelRef.current,
      );
    }
    document.body.style.removeProperty("--cursor");
  }, []);

  useEffect(() => {
    handlePointerMoveRef.current = (e: PointerEvent) => {
      const resize = resizeRef.current;
      if (!resize || e.pointerId !== resize.pointerId) return;

      const deltaX = Math.abs(e.clientX - resize.startClientX);
      if (!resize.isResizing && deltaX < DRAG_THRESHOLD_PX) return;

      if (!resize.isResizing) {
        resize.isResizing = true;
        document.body.style.setProperty(
          "--cursor",
          resize.edge === "move" ? "grabbing" : "col-resize",
        );
      }

      const container = allDayContainerRef.current;
      if (!container) return;

      const rect = container.getBoundingClientRect();
      const colWidth = dayColumnWidthRef.current;
      const currentDays = daysRef.current;
      const columnIndex = clamp(
        Math.floor((e.clientX - rect.left) / colWidth),
        0,
        currentDays.length - 1,
      );

      let newStartColumn = resize.originalStartColumn;
      let newEndColumn = resize.originalEndColumn;

      if (resize.edge === "move") {
        const span = resize.originalEndColumn - resize.originalStartColumn;
        const delta = columnIndex - resize.startColumnIndex;
        newStartColumn = clamp(
          resize.originalStartColumn + delta,
          0,
          currentDays.length - 1 - span,
        );
        newEndColumn = newStartColumn + span;
      } else if (resize.edge === "right") {
        newEndColumn = Math.max(columnIndex, resize.originalStartColumn);
      } else {
        newStartColumn = Math.min(columnIndex, resize.originalEndColumn);
      }

      resize.currentStartColumn = newStartColumn;
      resize.currentEndColumn = newEndColumn;

      setAllDayResizeState({
        eventId: resize.eventId,
        event: resize.event,
        originalStartColumn: resize.originalStartColumn,
        originalEndColumn: resize.originalEndColumn,
        currentStartColumn: newStartColumn,
        currentEndColumn: newEndColumn,
        edge: resize.edge,
        isResizing: true,
        ...(resize.edge === "move"
          ? {
              clientX: e.clientX,
              clientY: e.clientY,
              cursorOffsetX: resize.cursorOffsetX,
              cursorOffsetY: resize.cursorOffsetY,
            }
          : {}),
      });
    };

    handlePointerUpRef.current = (e: PointerEvent) => {
      const resize = resizeRef.current;
      if (!resize || e.pointerId !== resize.pointerId) return;

      cleanup();
      resizeRef.current = null;
      setAllDayResizeState(null);

      // Touch selects on release, after the gesture, rather than on press
      if (resize.pointerType === "touch") {
        onEventClickRef.current?.(resize.event);
      }
      if (!resize.isResizing) return;
      // A move swaps the pressed bar for a ghost, so the browser's click
      // lands on the row and would clear the selection
      suppressNextClick(resize.pointerType);

      // Commit from the handler, never from inside a state updater:
      // updaters run during render, and calling the parent's setState
      // there triggers "Cannot update a component while rendering".
      // A repeating event's generated occurrence isn't in `events`: commit
      // the copy the gesture started with
      const event =
        eventsRef.current.find((e) => e.id === resize.eventId) ?? resize.event;

      // The columns are clipped to the rendered days, so they only say
      // which edge moved and how far. An edge that did not move keeps the
      // event's own date.
      const startMoved =
        resize.currentStartColumn !== resize.originalStartColumn;
      const endMoved = resize.currentEndColumn !== resize.originalEndColumn;
      if (!startMoved && !endMoved) return;

      let newStart = event.start;
      let newEnd = event.end;

      if (resize.edge === "move") {
        const daysMoved =
          resize.currentStartColumn - resize.originalStartColumn;
        newStart = addDays(event.start, daysMoved);
        newEnd = addDays(event.end, daysMoved);
      } else {
        const currentDays = daysRef.current;
        const startDay = currentDays[resize.currentStartColumn];
        const endDay = currentDays[resize.currentEndColumn];
        if (!startDay || !endDay) return;
        if (startMoved) newStart = atTimeOf(startDay, event.start);
        if (endMoved) newEnd = atTimeOf(endDay, event.end);
      }

      // A timed event keeps its times of day, so an edge can land on a day
      // where the end would not be after the start
      if (!event.isAllDay && newEnd.getTime() <= newStart.getTime()) return;

      // The event keeps its own isAllDay: its length never decides it
      onEventChangeRef.current?.({ ...event, start: newStart, end: newEnd });
    };

    // The browser took the pointer over (e.g. for a system gesture): drop
    // the gesture without committing it
    handlePointerCancelRef.current = (e: PointerEvent) => {
      const resize = resizeRef.current;
      if (!resize || e.pointerId !== resize.pointerId) return;

      cleanup();
      resizeRef.current = null;
      setAllDayResizeState(null);
    };
  }, [allDayContainerRef, cleanup]);

  const beginResize = useCallback(
    (
      { clientX, pointerId, pointerType }: PointerGestureStart,
      event: CalendarEvent,
      edge: "left" | "right" | "move",
      startColumn: number,
      endColumn: number,
    ) => {
      // Mouse and pen select the event immediately
      if (pointerType !== "touch") onEventClickRef.current?.(event);

      // Compute the column under the cursor at the start for move delta
      const container = allDayContainerRef.current;
      let startColumnIndex = startColumn;
      let cursorOffsetX = 0;
      const cursorOffsetY = 0;
      if (container) {
        const rect = container.getBoundingClientRect();
        const colWidth = dayColumnWidthRef.current;
        startColumnIndex = clamp(
          Math.floor((clientX - rect.left) / colWidth),
          0,
          daysRef.current.length - 1,
        );
        // Compute offset from cursor to the event element's top-left
        const eventLeft = rect.left + startColumn * colWidth;
        cursorOffsetX = clientX - eventLeft;
      }

      resizeRef.current = {
        eventId: event.id,
        event,
        pointerId,
        pointerType,
        edge,
        startClientX: clientX,
        isResizing: false,
        originalStartColumn: startColumn,
        originalEndColumn: endColumn,
        startColumnIndex,
        cursorOffsetX,
        cursorOffsetY,
        currentStartColumn: startColumn,
        currentEndColumn: endColumn,
      };

      setAllDayResizeState({
        eventId: event.id,
        event,
        originalStartColumn: startColumn,
        originalEndColumn: endColumn,
        currentStartColumn: startColumn,
        currentEndColumn: endColumn,
        edge,
        isResizing: false,
      });

      if (handlePointerMoveRef.current) {
        window.addEventListener("pointermove", handlePointerMoveRef.current);
      }
      if (handlePointerUpRef.current) {
        window.addEventListener("pointerup", handlePointerUpRef.current);
      }
      if (handlePointerCancelRef.current) {
        window.addEventListener(
          "pointercancel",
          handlePointerCancelRef.current,
        );
      }
    },
    [allDayContainerRef],
  );

  const handleAllDayResizePointerDown = useCallback(
    (
      e: React.PointerEvent<HTMLElement>,
      event: CalendarEvent,
      edge: "left" | "right" | "move",
      startColumn: number,
      endColumn: number,
    ) => {
      if (!isPrimaryPress(e)) return;
      e.stopPropagation();
      startGesture(e, (start) =>
        beginResize(start, event, edge, startColumn, endColumn),
      );
    },
    [startGesture, beginResize],
  );

  useEffect(() => {
    return cleanup;
  }, [cleanup]);

  return { allDayResizeState, handleAllDayResizePointerDown };
}

"use client";

import { isSameDay } from "date-fns";
import { useCallback, useEffect, useRef, useState } from "react";
import {
  usePointerGesture,
  suppressNextClick,
} from "@/hooks/use-pointer-gesture";
import { snapToGrid } from "@/lib/event-utils";
import type {
  CalendarEvent,
  EventDragState,
  PointerGestureStart,
} from "@/components/week-view-types";

interface UseEventDragOptions {
  hourHeight: number;
  scrollContainerRef: React.RefObject<HTMLDivElement | null>;
  events: CalendarEvent[];
  days: Date[];
  dayColumnWidth: number;
  timeAxisWidth: number;
  /** Minute step the dragged start snaps to */
  snapMinutes: number;
  /** First visible hour: the top of the grid, and the earliest start */
  dayStartHour: number;
  /** Hour the grid ends at: the latest end */
  dayEndHour: number;
  /** Days `onDragNavigate` moves when the cursor is held at a side edge */
  edgeNavigationDays: number;
  onEventChange?: (event: CalendarEvent) => void;
  onEventClick?: (event: CalendarEvent) => void;
  onDragNavigate?: (daysDelta: number) => void;
}

interface UseEventDragReturn {
  dragState: EventDragState | null;
  handleEventPointerDown: (
    e: React.PointerEvent<HTMLElement>,
    event: CalendarEvent,
  ) => void;
}

const DRAG_THRESHOLD_PX = 4;
const EDGE_ZONE_PX = 40;
const EDGE_NAV_DELAY_MS = 500;
const EDGE_NAV_REPEAT_MS = 800;
const AUTO_SCROLL_ZONE_PX = 60;
const AUTO_SCROLL_MAX_SPEED = 12;

function addMinutesToDate(date: Date, minutes: number): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  result.setMinutes(minutes);
  return result;
}

function clamp(value: number, min: number, max: number): number {
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

interface DragInfo {
  eventId: string;
  event: CalendarEvent;
  /** Pointer driving the drag; moves from other pointers are ignored */
  pointerId: number;
  /** "mouse", "pen" or "touch" */
  pointerType: string;
  startClientY: number;
  startClientX: number;
  offsetWithinEvent: number;
  offsetWithinEventX: number;
  isDragging: boolean;
  durationMinutes: number;
  /** Latest snapped start, committed to the parent on pointerup */
  currentStart: Date;
  /** Latest snapped end, committed to the parent on pointerup */
  currentEnd: Date;
}

export function useEventDrag({
  hourHeight,
  scrollContainerRef,
  events,
  days,
  dayColumnWidth,
  timeAxisWidth,
  snapMinutes,
  dayStartHour,
  dayEndHour,
  edgeNavigationDays,
  onEventChange,
  onEventClick,
  onDragNavigate,
}: UseEventDragOptions): UseEventDragReturn {
  const [dragState, setDragState] = useState<EventDragState | null>(null);
  const { startGesture } = usePointerGesture({
    containerRef: scrollContainerRef,
  });

  const dragRef = useRef<DragInfo | null>(null);
  const onEventChangeRef = useRef(onEventChange);
  const onEventClickRef = useRef(onEventClick);
  const onDragNavigateRef = useRef(onDragNavigate);
  const eventsRef = useRef(events);
  const hourHeightRef = useRef(hourHeight);
  const daysRef = useRef(days);
  const dayColumnWidthRef = useRef(dayColumnWidth);
  const timeAxisWidthRef = useRef(timeAxisWidth);
  const snapMinutesRef = useRef(snapMinutes);
  const dayStartHourRef = useRef(dayStartHour);
  const dayEndHourRef = useRef(dayEndHour);
  const edgeNavigationDaysRef = useRef(edgeNavigationDays);

  useEffect(() => {
    onEventChangeRef.current = onEventChange;
  }, [onEventChange]);
  useEffect(() => {
    onEventClickRef.current = onEventClick;
  }, [onEventClick]);
  useEffect(() => {
    onDragNavigateRef.current = onDragNavigate;
  }, [onDragNavigate]);
  useEffect(() => {
    eventsRef.current = events;
  }, [events]);
  useEffect(() => {
    hourHeightRef.current = hourHeight;
  }, [hourHeight]);
  useEffect(() => {
    daysRef.current = days;
  }, [days]);
  useEffect(() => {
    dayColumnWidthRef.current = dayColumnWidth;
  }, [dayColumnWidth]);
  useEffect(() => {
    timeAxisWidthRef.current = timeAxisWidth;
  }, [timeAxisWidth]);
  useEffect(() => {
    snapMinutesRef.current = snapMinutes;
  }, [snapMinutes]);
  useEffect(() => {
    dayStartHourRef.current = dayStartHour;
  }, [dayStartHour]);
  useEffect(() => {
    dayEndHourRef.current = dayEndHour;
  }, [dayEndHour]);
  useEffect(() => {
    edgeNavigationDaysRef.current = edgeNavigationDays;
  }, [edgeNavigationDays]);

  // Edge navigation timer refs
  const edgeNavTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const edgeNavDirectionRef = useRef<number | null>(null);

  // Auto-scroll RAF ref
  const autoScrollRAFRef = useRef<number | null>(null);
  const autoScrollSpeedRef = useRef(0);

  // Store handlers in refs to break the circular dependency
  const handlePointerMoveRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePointerUpRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePointerCancelRef = useRef<((e: PointerEvent) => void) | null>(
    null,
  );

  const cancelEdgeNav = useCallback(() => {
    if (edgeNavTimerRef.current !== null) {
      clearTimeout(edgeNavTimerRef.current);
      edgeNavTimerRef.current = null;
    }
    edgeNavDirectionRef.current = null;
  }, []);

  const cancelAutoScroll = useCallback(() => {
    if (autoScrollRAFRef.current !== null) {
      cancelAnimationFrame(autoScrollRAFRef.current);
      autoScrollRAFRef.current = null;
    }
    autoScrollSpeedRef.current = 0;
  }, []);

  const cleanup = useCallback(() => {
    if (handlePointerMoveRef.current) {
      window.removeEventListener("pointermove", handlePointerMoveRef.current);
    }
    if (handlePointerUpRef.current) {
      window.removeEventListener("pointerup", handlePointerUpRef.current);
    }
    if (handlePointerCancelRef.current) {
      window.removeEventListener(
        "pointercancel",
        handlePointerCancelRef.current,
      );
    }
    cancelEdgeNav();
    cancelAutoScroll();
  }, [cancelEdgeNav, cancelAutoScroll]);

  // Auto-scroll loop
  const startAutoScrollLoop = useCallback(() => {
    if (autoScrollRAFRef.current !== null) return;

    const tick = () => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const speed = autoScrollSpeedRef.current;
      if (speed === 0) {
        autoScrollRAFRef.current = null;
        return;
      }

      container.scrollTop += speed;
      autoScrollRAFRef.current = requestAnimationFrame(tick);
    };

    autoScrollRAFRef.current = requestAnimationFrame(tick);
  }, [scrollContainerRef]);

  const scheduleEdgeNav = useCallback(
    (direction: number) => {
      if (edgeNavDirectionRef.current === direction) return;

      cancelEdgeNav();
      edgeNavDirectionRef.current = direction;

      const fireNav = () => {
        onDragNavigateRef.current?.(direction);
        edgeNavTimerRef.current = setTimeout(fireNav, EDGE_NAV_REPEAT_MS);
      };

      edgeNavTimerRef.current = setTimeout(fireNav, EDGE_NAV_DELAY_MS);
    },
    [cancelEdgeNav],
  );

  // Initialize the handlers once (stable references via refs)
  useEffect(() => {
    handlePointerMoveRef.current = (e: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag || e.pointerId !== drag.pointerId) return;

      const deltaY = Math.abs(e.clientY - drag.startClientY);
      const deltaX = Math.abs(e.clientX - drag.startClientX);
      if (
        !drag.isDragging &&
        deltaY < DRAG_THRESHOLD_PX &&
        deltaX < DRAG_THRESHOLD_PX
      )
        return;

      if (!drag.isDragging) {
        drag.isDragging = true;
      }

      const container = scrollContainerRef.current;
      if (!container) return;

      const containerRect = container.getBoundingClientRect();
      const scrollTop = container.scrollTop;
      const absoluteY =
        e.clientY - containerRect.top + scrollTop - drag.offsetWithinEvent;
      const absoluteX =
        e.clientX - containerRect.left - drag.offsetWithinEventX;
      // The grid's top edge is `dayStartHour`, not midnight
      const visibleStartMinutes = dayStartHourRef.current * 60;
      const visibleEndMinutes = dayEndHourRef.current * 60;
      const rawMinutes =
        visibleStartMinutes + (absoluteY / hourHeightRef.current) * 60;
      const snappedStartMinutes = snapToGrid(
        rawMinutes,
        snapMinutesRef.current,
      );
      const clampedStart = Math.max(
        visibleStartMinutes,
        Math.min(snappedStartMinutes, visibleEndMinutes - drag.durationMinutes),
      );

      // Column detection — based on raw cursor position over the grid
      const colWidth = dayColumnWidthRef.current;
      const visibleDays = daysRef.current;
      const gridLeftEdge = containerRect.left + timeAxisWidthRef.current;
      const cursorInGrid = e.clientX - gridLeftEdge;
      const columnIndex = clamp(
        Math.floor(cursorInGrid / colWidth),
        0,
        visibleDays.length - 1,
      );
      const targetDay = visibleDays[columnIndex];

      const currentStart = addMinutesToDate(targetDay, clampedStart);
      const currentEnd = addMinutesToDate(
        targetDay,
        clampedStart + drag.durationMinutes,
      );

      drag.currentStart = currentStart;
      drag.currentEnd = currentEnd;

      setDragState({
        eventId: drag.eventId,
        event: drag.event,
        originalStart: drag.event.start,
        originalEnd: drag.event.end,
        currentStart,
        currentEnd,
        currentDate: targetDay,
        isDragging: true,
        cursorY: absoluteY,
        cursorX: absoluteX,
        clientX: e.clientX - drag.offsetWithinEventX,
        clientY: e.clientY - drag.offsetWithinEvent,
      });

      // Edge-of-view week navigation
      // Trigger when cursor is within EDGE_ZONE_PX of the grid boundary OR past it
      const cursorXInGrid = e.clientX - gridLeftEdge;
      const gridWidth = colWidth * visibleDays.length;

      if (cursorXInGrid < EDGE_ZONE_PX) {
        scheduleEdgeNav(-edgeNavigationDaysRef.current);
      } else if (cursorXInGrid > gridWidth - EDGE_ZONE_PX) {
        scheduleEdgeNav(edgeNavigationDaysRef.current);
      } else {
        cancelEdgeNav();
      }

      // Auto-scroll at top/bottom edges
      const cursorYInContainer = e.clientY - containerRect.top;
      const containerHeight = containerRect.height;

      if (cursorYInContainer < AUTO_SCROLL_ZONE_PX) {
        const dist = cursorYInContainer;
        autoScrollSpeedRef.current =
          -AUTO_SCROLL_MAX_SPEED * (1 - dist / AUTO_SCROLL_ZONE_PX);
        startAutoScrollLoop();
      } else if (cursorYInContainer > containerHeight - AUTO_SCROLL_ZONE_PX) {
        const dist = containerHeight - cursorYInContainer;
        autoScrollSpeedRef.current =
          AUTO_SCROLL_MAX_SPEED * (1 - dist / AUTO_SCROLL_ZONE_PX);
        startAutoScrollLoop();
      } else {
        cancelAutoScroll();
      }
    };

    handlePointerUpRef.current = (e: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag || e.pointerId !== drag.pointerId) return;

      cleanup();
      dragRef.current = null;
      setDragState(null);

      // Touch selects on release, after the drag, rather than on press
      if (drag.pointerType === "touch") onEventClickRef.current?.(drag.event);
      if (!drag.isDragging) return;
      suppressNextClick(drag.pointerType);

      // Commit from the handler, never from inside a state updater:
      // updaters run during render, and calling the parent's setState
      // there triggers "Cannot update a component while rendering".
      // A repeating event's generated occurrence isn't in `events`: commit
      // the copy the gesture started with
      const event =
        eventsRef.current.find((e) => e.id === drag.eventId) ?? drag.event;

      onEventChangeRef.current?.({
        ...event,
        start: drag.currentStart,
        end: drag.currentEnd,
      });
    };

    // The browser took the pointer over (e.g. for a system gesture): drop
    // the drag without committing it
    handlePointerCancelRef.current = (e: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag || e.pointerId !== drag.pointerId) return;

      cleanup();
      dragRef.current = null;
      setDragState(null);
    };
  }, [
    scrollContainerRef,
    cleanup,
    scheduleEdgeNav,
    cancelEdgeNav,
    cancelAutoScroll,
    startAutoScrollLoop,
  ]);

  const beginDrag = useCallback(
    (
      {
        clientX,
        clientY,
        pointerId,
        pointerType,
        element,
      }: PointerGestureStart,
      event: CalendarEvent,
    ) => {
      // Mouse and pen select the event immediately
      if (pointerType !== "touch") onEventClickRef.current?.(event);

      const container = scrollContainerRef.current;
      if (!container) return;

      // Compute offset within the event element
      const targetRect = element.getBoundingClientRect();
      const offsetWithinEvent = clientY - targetRect.top;
      const offsetWithinEventX = clientX - targetRect.left;

      const startMinutes =
        event.start.getHours() * 60 + event.start.getMinutes();
      // An end at the next midnight is minute 1440 of the event's day, not 0
      const endMinutes = isSameDay(event.start, event.end)
        ? event.end.getHours() * 60 + event.end.getMinutes()
        : 1440;
      const durationMinutes = endMinutes - startMinutes;

      dragRef.current = {
        eventId: event.id,
        event,
        pointerId,
        pointerType,
        startClientY: clientY,
        startClientX: clientX,
        offsetWithinEvent,
        offsetWithinEventX,
        isDragging: false,
        durationMinutes,
        currentStart: event.start,
        currentEnd: event.end,
      };

      setDragState({
        eventId: event.id,
        event,
        originalStart: event.start,
        originalEnd: event.end,
        currentStart: event.start,
        currentEnd: event.end,
        currentDate: event.start,
        isDragging: false,
        cursorY: 0,
        cursorX: 0,
        clientX: 0,
        clientY: 0,
      });

      if (handlePointerMoveRef.current) {
        window.addEventListener("pointermove", handlePointerMoveRef.current);
      }
      if (handlePointerUpRef.current) {
        window.addEventListener("pointerup", handlePointerUpRef.current);
      }
      if (handlePointerCancelRef.current) {
        window.addEventListener(
          "pointercancel",
          handlePointerCancelRef.current,
        );
      }
    },
    [scrollContainerRef],
  );

  const handleEventPointerDown = useCallback(
    (e: React.PointerEvent<HTMLElement>, event: CalendarEvent) => {
      startGesture(e, (start) => beginDrag(start, event));
    },
    [startGesture, beginDrag],
  );

  // Cleanup on unmount
  useEffect(() => {
    return cleanup;
  }, [cleanup]);

  return { dragState, handleEventPointerDown };
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  isPrimaryPress,
  suppressNextClick,
  usePointerGesture,
} from "@/hooks/use-pointer-gesture";
import { getClickedEventRange, getDrawnEventRange } from "@/lib/event-utils";
import type { TimeGridPoint } from "@/lib/event-utils";
import type {
  EventDrawPhase,
  NewEventRange,
  PointerGestureStart,
} from "@/components/week-view-types";

interface UseEventDrawOptions {
  hourHeight: number;
  scrollContainerRef: React.RefObject<HTMLDivElement | null>;
  /** Days on screen, left to right: the columns a drag can reach */
  days: Date[];
  dayColumnWidth: number;
  timeAxisWidth: number;
  /** Minute step both ends of the drawn range snap to, and its shortest length */
  snapMinutes: number;
  /** Length of the event a touch long press starts with, before the finger moves */
  defaultEventDuration: number;
  /** First visible hour: the top of the grid, and the earliest start */
  dayStartHour: number;
  /** Hour the grid ends at: the latest end */
  dayEndHour: number;
  /**
   * Called with the range drawn so far: "start" once the press becomes a
   * drag, "move" each time the snapped range changes, "end" on release
   */
  onDraw?: (range: NewEventRange, phase: EventDrawPhase) => void;
  /** Called when a drag that started drawing is dropped: Escape, or the browser took the pointer */
  onCancel?: () => void;
}

interface UseEventDrawReturn {
  /** Whether a drag is drawing a new event right now */
  isDrawing: boolean;
  /** Starts a draw gesture from a pointerdown on a day column's empty space */
  handleDrawPointerDown: (
    e: React.PointerEvent<HTMLElement>,
    columnDate: Date,
  ) => void;
}

/**
 * How far (px) the pointer travels before a press on empty space draws an
 * event. Matches the drag and resize thresholds, so a click never draws.
 */
const DRAW_THRESHOLD_PX = 4;
const AUTO_SCROLL_ZONE_PX = 60;
const AUTO_SCROLL_MAX_SPEED = 12;

function clamp(value: number, min: number, max: number): number {
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

/** A press on empty grid space that may become, or is, a drawn event */
interface DrawInfo {
  /** Pointer driving the gesture; moves from other pointers are ignored */
  pointerId: number;
  /** "mouse", "pen" or "touch" */
  pointerType: string;
  startClientX: number;
  startClientY: number;
  /** Where the press landed: the end of the range that stays put */
  anchor: TimeGridPoint;
  /** Whether the press has started drawing (reported "start") */
  isDrawing: boolean;
  /** Whether the pointer has travelled past the threshold */
  hasMoved: boolean;
  /** Range reported last, reported again as the final one on release */
  range: NewEventRange | null;
}

/**
 * Draws a new event on the time grid, as Notion Calendar does: press empty
 * space and drag. The press is the anchor; the range runs from it to the
 * pointer, up or down and across day columns, snapped to `snapMinutes`.
 * Mouse and pen draw once the pointer has moved; touch draws from a long
 * press, starting with a `defaultEventDuration` event at the pressed slot.
 * Escape or a `pointercancel` mid-drag drops it through `onCancel`.
 */
export function useEventDraw({
  hourHeight,
  scrollContainerRef,
  days,
  dayColumnWidth,
  timeAxisWidth,
  snapMinutes,
  defaultEventDuration,
  dayStartHour,
  dayEndHour,
  onDraw,
  onCancel,
}: UseEventDrawOptions): UseEventDrawReturn {
  const [isDrawing, setIsDrawing] = useState(false);
  const { startGesture } = usePointerGesture({
    containerRef: scrollContainerRef,
  });

  const drawRef = useRef<DrawInfo | null>(null);
  const onDrawRef = useRef(onDraw);
  const onCancelRef = useRef(onCancel);
  const hourHeightRef = useRef(hourHeight);
  const daysRef = useRef(days);
  const dayColumnWidthRef = useRef(dayColumnWidth);
  const timeAxisWidthRef = useRef(timeAxisWidth);
  const snapMinutesRef = useRef(snapMinutes);
  const defaultEventDurationRef = useRef(defaultEventDuration);
  const dayStartHourRef = useRef(dayStartHour);
  const dayEndHourRef = useRef(dayEndHour);

  useEffect(() => {
    onDrawRef.current = onDraw;
  }, [onDraw]);
  useEffect(() => {
    onCancelRef.current = onCancel;
  }, [onCancel]);
  useEffect(() => {
    hourHeightRef.current = hourHeight;
  }, [hourHeight]);
  useEffect(() => {
    daysRef.current = days;
  }, [days]);
  useEffect(() => {
    dayColumnWidthRef.current = dayColumnWidth;
  }, [dayColumnWidth]);
  useEffect(() => {
    timeAxisWidthRef.current = timeAxisWidth;
  }, [timeAxisWidth]);
  useEffect(() => {
    snapMinutesRef.current = snapMinutes;
  }, [snapMinutes]);
  useEffect(() => {
    defaultEventDurationRef.current = defaultEventDuration;
  }, [defaultEventDuration]);
  useEffect(() => {
    dayStartHourRef.current = dayStartHour;
  }, [dayStartHour]);
  useEffect(() => {
    dayEndHourRef.current = dayEndHour;
  }, [dayEndHour]);

  const autoScrollRAFRef = useRef<number | null>(null);
  const autoScrollSpeedRef = useRef(0);

  const handlePointerMoveRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePointerUpRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePointerCancelRef = useRef<((e: PointerEvent) => void) | null>(
    null,
  );
  const handleKeyDownRef = useRef<((e: KeyboardEvent) => void) | null>(null);

  const cancelAutoScroll = useCallback(() => {
    if (autoScrollRAFRef.current !== null) {
      cancelAnimationFrame(autoScrollRAFRef.current);
      autoScrollRAFRef.current = null;
    }
    autoScrollSpeedRef.current = 0;
  }, []);

  const cleanup = useCallback(() => {
    if (handlePointerMoveRef.current) {
      window.removeEventListener("pointermove", handlePointerMoveRef.current);
    }
    if (handlePointerUpRef.current) {
      window.removeEventListener("pointerup", handlePointerUpRef.current);
    }
    if (handlePointerCancelRef.current) {
      window.removeEventListener(
        "pointercancel",
        handlePointerCancelRef.current,
      );
    }
    if (handleKeyDownRef.current) {
      window.removeEventListener("keydown", handleKeyDownRef.current, true);
    }
    cancelAutoScroll();
  }, [cancelAutoScroll]);

  const startAutoScrollLoop = useCallback(() => {
    if (autoScrollRAFRef.current !== null) return;

    const tick = () => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const speed = autoScrollSpeedRef.current;
      if (speed === 0) {
        autoScrollRAFRef.current = null;
        return;
      }

      container.scrollTop += speed;
      autoScrollRAFRef.current = requestAnimationFrame(tick);
    };

    autoScrollRAFRef.current = requestAnimationFrame(tick);
  }, [scrollContainerRef]);

  /** The grid point under a viewport position: its day column and clock minutes */
  const getPointAt = useCallback(
    (clientX: number, clientY: number, fallbackDay: Date): TimeGridPoint => {
      const container = scrollContainerRef.current;
      if (!container) return { day: fallbackDay, minutes: 0 };

      const containerRect = container.getBoundingClientRect();
      const absoluteY = clientY - containerRect.top + container.scrollTop;
      // The grid's top edge is `dayStartHour`, not midnight
      const minutes =
        dayStartHourRef.current * 60 + (absoluteY / hourHeightRef.current) * 60;

      const visibleDays = daysRef.current;
      const colWidth = dayColumnWidthRef.current;
      if (visibleDays.length === 0 || colWidth <= 0) {
        return { day: fallbackDay, minutes };
      }
      const gridLeftEdge = containerRect.left + timeAxisWidthRef.current;
      const columnIndex = clamp(
        Math.floor((clientX - gridLeftEdge) / colWidth),
        0,
        visibleDays.length - 1,
      );
      return { day: visibleDays[columnIndex], minutes };
    },
    [scrollContainerRef],
  );

  /** Ends the gesture without a draft: Escape, or the browser took the pointer */
  const cancelDraw = useCallback(() => {
    const draw = drawRef.current;
    if (!draw) return;
    cleanup();
    drawRef.current = null;
    setIsDrawing(false);
    if (draw.isDrawing) onCancelRef.current?.();
  }, [cleanup]);

  useEffect(() => {
    handlePointerMoveRef.current = (e: PointerEvent) => {
      const draw = drawRef.current;
      if (!draw || e.pointerId !== draw.pointerId) return;

      if (!draw.hasMoved) {
        const distance = Math.hypot(
          e.clientX - draw.startClientX,
          e.clientY - draw.startClientY,
        );
        if (distance < DRAW_THRESHOLD_PX) return;
        draw.hasMoved = true;
      }

      const range = getDrawnEventRange(
        draw.anchor,
        getPointAt(e.clientX, e.clientY, draw.anchor.day),
        {
          snapMinutes: snapMinutesRef.current,
          dayStartHour: dayStartHourRef.current,
          dayEndHour: dayEndHourRef.current,
        },
      );
      const isSameRange =
        draw.range !== null &&
        draw.range.start.getTime() === range.start.getTime() &&
        draw.range.end.getTime() === range.end.getTime();
      draw.range = range;

      if (!draw.isDrawing) {
        draw.isDrawing = true;
        setIsDrawing(true);
        onDrawRef.current?.(range, "start");
      } else if (!isSameRange) {
        onDrawRef.current?.(range, "move");
      }

      // Auto-scroll at top/bottom edges
      const container = scrollContainerRef.current;
      if (!container) return;
      const containerRect = container.getBoundingClientRect();
      const cursorYInContainer = e.clientY - containerRect.top;

      if (cursorYInContainer < AUTO_SCROLL_ZONE_PX) {
        autoScrollSpeedRef.current =
          -AUTO_SCROLL_MAX_SPEED *
          (1 - Math.max(0, cursorYInContainer) / AUTO_SCROLL_ZONE_PX);
        startAutoScrollLoop();
        return;
      }
      if (cursorYInContainer > containerRect.height - AUTO_SCROLL_ZONE_PX) {
        const distance = Math.max(0, containerRect.height - cursorYInContainer);
        autoScrollSpeedRef.current =
          AUTO_SCROLL_MAX_SPEED * (1 - distance / AUTO_SCROLL_ZONE_PX);
        startAutoScrollLoop();
        return;
      }
      cancelAutoScroll();
    };

    handlePointerUpRef.current = (e: PointerEvent) => {
      const draw = drawRef.current;
      if (!draw || e.pointerId !== draw.pointerId) return;

      cleanup();
      drawRef.current = null;
      setIsDrawing(false);

      if (!draw.isDrawing || !draw.range) return;
      // The click that follows lands on the grid and would read as a
      // background click that throws the new draft away
      suppressNextClick(draw.pointerType);
      onDrawRef.current?.(draw.range, "end");
    };

    // The browser took the pointer over (e.g. for a system gesture): drop
    // the draft
    handlePointerCancelRef.current = (e: PointerEvent) => {
      const draw = drawRef.current;
      if (!draw || e.pointerId !== draw.pointerId) return;
      cancelDraw();
    };

    // Escape mid-drag drops the draft, as in Notion Calendar. The key goes
    // on to the calendar's own Escape, which clears the selection anyway.
    handleKeyDownRef.current = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      cancelDraw();
    };
  }, [
    scrollContainerRef,
    cleanup,
    cancelDraw,
    cancelAutoScroll,
    startAutoScrollLoop,
    getPointAt,
  ]);

  const beginDraw = useCallback(
    (
      { clientX, clientY, pointerId, pointerType }: PointerGestureStart,
      columnDate: Date,
    ) => {
      const anchor = getPointAt(clientX, clientY, columnDate);
      const draw: DrawInfo = {
        pointerId,
        pointerType,
        startClientX: clientX,
        startClientY: clientY,
        // The pressed column is the anchor's day, whatever X resolves to
        anchor: { day: columnDate, minutes: anchor.minutes },
        isDrawing: false,
        hasMoved: false,
        range: null,
      };
      drawRef.current = draw;

      // A long press draws at once: a finger has no double-click
      if (pointerType === "touch") {
        draw.range = getClickedEventRange(columnDate, anchor.minutes, {
          snapMinutes: snapMinutesRef.current,
          defaultEventDuration: defaultEventDurationRef.current,
          dayStartHour: dayStartHourRef.current,
          dayEndHour: dayEndHourRef.current,
        });
        draw.isDrawing = true;
        setIsDrawing(true);
        onDrawRef.current?.(draw.range, "start");
      }

      if (handlePointerMoveRef.current) {
        window.addEventListener("pointermove", handlePointerMoveRef.current);
      }
      if (handlePointerUpRef.current) {
        window.addEventListener("pointerup", handlePointerUpRef.current);
      }
      if (handlePointerCancelRef.current) {
        window.addEventListener(
          "pointercancel",
          handlePointerCancelRef.current,
        );
      }
      if (handleKeyDownRef.current) {
        window.addEventListener("keydown", handleKeyDownRef.current, true);
      }
    },
    [getPointAt],
  );

  const handleDrawPointerDown = useCallback(
    (e: React.PointerEvent<HTMLElement>, columnDate: Date) => {
      if (!isPrimaryPress(e)) return;
      startGesture(e, (start) => beginDraw(start, columnDate));
    },
    [startGesture, beginDraw],
  );

  useEffect(() => {
    return cleanup;
  }, [cleanup]);

  return { isDrawing, handleDrawPointerDown };
}

"use client";

import { isSameDay, startOfDay, subDays } from "date-fns";
import { useCallback, useEffect, useRef, useState } from "react";
import {
  isPrimaryPress,
  suppressNextClick,
  usePointerGesture,
} from "@/hooks/use-pointer-gesture";
import { snapToGrid } from "@/lib/event-utils";
import type {
  CalendarEvent,
  EventResizeState,
  PointerGestureStart,
} from "@/components/week-view-types";

interface UseEventResizeOptions {
  hourHeight: number;
  scrollContainerRef: React.RefObject<HTMLDivElement | null>;
  events: CalendarEvent[];
  days: Date[];
  dayColumnWidth: number;
  timeAxisWidth: number;
  /** Minute step the dragged edge snaps to, and the shortest duration */
  snapMinutes: number;
  /** First visible hour: the top of the grid, and the earliest start */
  dayStartHour: number;
  /** Hour the grid ends at: the latest end */
  dayEndHour: number;
  /** Days `onResizeNavigate` moves when the cursor is held at a side edge */
  edgeNavigationDays: number;
  onEventChange?: (event: CalendarEvent) => void;
  onEventClick?: (event: CalendarEvent) => void;
  onResizeNavigate?: (daysDelta: number) => void;
}

interface UseEventResizeReturn {
  resizeState: EventResizeState | null;
  handleResizePointerDown: (
    e: React.PointerEvent<HTMLElement>,
    event: CalendarEvent,
    edge: "top" | "bottom",
  ) => void;
}

const DRAG_THRESHOLD_PX = 4;
const AUTO_SCROLL_ZONE_PX = 60;
const AUTO_SCROLL_MAX_SPEED = 12;
const EDGE_ZONE_PX = 40;
const EDGE_NAV_DELAY_MS = 500;
const EDGE_NAV_REPEAT_MS = 800;

function addMinutesToDate(date: Date, minutes: number): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  result.setMinutes(minutes);
  return result;
}

function clamp(value: number, min: number, max: number): number {
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

interface ResizeInfo {
  eventId: string;
  event: CalendarEvent;
  /** Pointer driving the resize; moves from other pointers are ignored */
  pointerId: number;
  /** "mouse", "pen" or "touch" */
  pointerType: string;
  edge: "top" | "bottom";
  startClientY: number;
  isResizing: boolean;
  originalStartMinutes: number;
  originalEndMinutes: number;
  originalStartDate: Date;
  originalEndDate: Date;
  /** Latest snapped start, committed to the parent on pointerup */
  currentStart: Date;
  /** Latest snapped end, committed to the parent on pointerup */
  currentEnd: Date;
}

export function useEventResize({
  hourHeight,
  scrollContainerRef,
  events,
  days,
  dayColumnWidth,
  timeAxisWidth,
  snapMinutes,
  dayStartHour,
  dayEndHour,
  edgeNavigationDays,
  onEventChange,
  onEventClick,
  onResizeNavigate,
}: UseEventResizeOptions): UseEventResizeReturn {
  const [resizeState, setResizeState] = useState<EventResizeState | null>(null);
  const { startGesture } = usePointerGesture({
    containerRef: scrollContainerRef,
  });

  const resizeRef = useRef<ResizeInfo | null>(null);
  const onEventChangeRef = useRef(onEventChange);
  const onEventClickRef = useRef(onEventClick);
  const onResizeNavigateRef = useRef(onResizeNavigate);
  const eventsRef = useRef(events);
  const hourHeightRef = useRef(hourHeight);
  const daysRef = useRef(days);
  const dayColumnWidthRef = useRef(dayColumnWidth);
  const timeAxisWidthRef = useRef(timeAxisWidth);
  const snapMinutesRef = useRef(snapMinutes);
  const dayStartHourRef = useRef(dayStartHour);
  const dayEndHourRef = useRef(dayEndHour);
  const edgeNavigationDaysRef = useRef(edgeNavigationDays);

  useEffect(() => {
    onEventChangeRef.current = onEventChange;
  }, [onEventChange]);
  useEffect(() => {
    onEventClickRef.current = onEventClick;
  }, [onEventClick]);
  useEffect(() => {
    onResizeNavigateRef.current = onResizeNavigate;
  }, [onResizeNavigate]);
  useEffect(() => {
    eventsRef.current = events;
  }, [events]);
  useEffect(() => {
    hourHeightRef.current = hourHeight;
  }, [hourHeight]);
  useEffect(() => {
    daysRef.current = days;
  }, [days]);
  useEffect(() => {
    dayColumnWidthRef.current = dayColumnWidth;
  }, [dayColumnWidth]);
  useEffect(() => {
    timeAxisWidthRef.current = timeAxisWidth;
  }, [timeAxisWidth]);
  useEffect(() => {
    snapMinutesRef.current = snapMinutes;
  }, [snapMinutes]);
  useEffect(() => {
    dayStartHourRef.current = dayStartHour;
  }, [dayStartHour]);
  useEffect(() => {
    dayEndHourRef.current = dayEndHour;
  }, [dayEndHour]);
  useEffect(() => {
    edgeNavigationDaysRef.current = edgeNavigationDays;
  }, [edgeNavigationDays]);

  const autoScrollRAFRef = useRef<number | null>(null);
  const autoScrollSpeedRef = useRef(0);
  const edgeNavTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const edgeNavDirectionRef = useRef<number | null>(null);

  const handlePointerMoveRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePointerUpRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePointerCancelRef = useRef<((e: PointerEvent) => void) | null>(
    null,
  );

  const cancelAutoScroll = useCallback(() => {
    if (autoScrollRAFRef.current !== null) {
      cancelAnimationFrame(autoScrollRAFRef.current);
      autoScrollRAFRef.current = null;
    }
    autoScrollSpeedRef.current = 0;
  }, []);

  const cancelEdgeNav = useCallback(() => {
    if (edgeNavTimerRef.current !== null) {
      clearTimeout(edgeNavTimerRef.current);
      edgeNavTimerRef.current = null;
    }
    edgeNavDirectionRef.current = null;
  }, []);

  const scheduleEdgeNav = useCallback(
    (direction: number) => {
      if (edgeNavDirectionRef.current === direction) return;

      cancelEdgeNav();
      edgeNavDirectionRef.current = direction;

      const fireNav = () => {
        onResizeNavigateRef.current?.(direction);
        edgeNavTimerRef.current = setTimeout(fireNav, EDGE_NAV_REPEAT_MS);
      };

      edgeNavTimerRef.current = setTimeout(fireNav, EDGE_NAV_DELAY_MS);
    },
    [cancelEdgeNav],
  );

  const cleanup = useCallback(() => {
    if (handlePointerMoveRef.current) {
      window.removeEventListener("pointermove", handlePointerMoveRef.current);
    }
    if (handlePointerUpRef.current) {
      window.removeEventListener("pointerup", handlePointerUpRef.current);
    }
    if (handlePointerCancelRef.current) {
      window.removeEventListener(
        "pointercancel",
        handlePointerCancelRef.current,
      );
    }
    cancelAutoScroll();
    cancelEdgeNav();
  }, [cancelAutoScroll, cancelEdgeNav]);

  const startAutoScrollLoop = useCallback(() => {
    if (autoScrollRAFRef.current !== null) return;

    const tick = () => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const speed = autoScrollSpeedRef.current;
      if (speed === 0) {
        autoScrollRAFRef.current = null;
        return;
      }

      container.scrollTop += speed;
      autoScrollRAFRef.current = requestAnimationFrame(tick);
    };

    autoScrollRAFRef.current = requestAnimationFrame(tick);
  }, [scrollContainerRef]);

  useEffect(() => {
    handlePointerMoveRef.current = (e: PointerEvent) => {
      const resize = resizeRef.current;
      if (!resize || e.pointerId !== resize.pointerId) return;

      const deltaY = Math.abs(e.clientY - resize.startClientY);
      if (!resize.isResizing && deltaY < DRAG_THRESHOLD_PX) return;

      if (!resize.isResizing) {
        resize.isResizing = true;
      }

      const container = scrollContainerRef.current;
      if (!container) return;

      const containerRect = container.getBoundingClientRect();
      const scrollTop = container.scrollTop;
      const absoluteY = e.clientY - containerRect.top + scrollTop;
      // The grid's top edge is `dayStartHour`, not midnight
      const visibleStartMinutes = dayStartHourRef.current * 60;
      const visibleEndMinutes = dayEndHourRef.current * 60;
      const rawMinutes =
        visibleStartMinutes + (absoluteY / hourHeightRef.current) * 60;
      const snapStep = snapMinutesRef.current;
      const snappedMinutes = snapToGrid(rawMinutes, snapStep);
      // Shortest event a resize can make: one snap step
      const minDurationMinutes = snapStep;

      let newStartMinutes = resize.originalStartMinutes;
      let newEndMinutes = resize.originalEndMinutes;
      let startDate = resize.originalStartDate;
      let endDate = resize.originalEndDate;

      // Column detection (shared for both edges)
      const colWidth = dayColumnWidthRef.current;
      const visibleDays = daysRef.current;
      const gridLeftEdge = containerRect.left + timeAxisWidthRef.current;
      const cursorInGrid = e.clientX - gridLeftEdge;
      const columnIndex = clamp(
        Math.floor(cursorInGrid / colWidth),
        0,
        visibleDays.length - 1,
      );
      const targetDay = visibleDays[columnIndex];

      // Unified anchor model: anchor is the opposite end of the grabbed edge
      const anchorDate =
        resize.edge === "bottom"
          ? resize.originalStartDate
          : resize.originalEndDate;
      const anchorMinutes =
        resize.edge === "bottom"
          ? resize.originalStartMinutes
          : resize.originalEndMinutes;

      const cursorTimestamp = targetDay.getTime() + snappedMinutes * 60000;
      const anchorTimestamp = anchorDate.getTime() + anchorMinutes * 60000;

      let effectiveEdge: "top" | "bottom";

      if (cursorTimestamp > anchorTimestamp) {
        // Cursor is after anchor → effective bottom
        effectiveEdge = "bottom";
        startDate = anchorDate;
        newStartMinutes = anchorMinutes;
        endDate = targetDay;
        newEndMinutes = clamp(
          snappedMinutes,
          visibleStartMinutes,
          visibleEndMinutes,
        );

        // Cross-day edge case: cursor at minute 0 on day right after anchor → treat as end-of-anchor-day
        if (!isSameDay(targetDay, anchorDate)) {
          const dayAfterAnchor = new Date(anchorDate);
          dayAfterAnchor.setDate(dayAfterAnchor.getDate() + 1);
          dayAfterAnchor.setHours(0, 0, 0, 0);

          if (isSameDay(targetDay, dayAfterAnchor) && snappedMinutes === 0) {
            newEndMinutes = 1440;
            endDate = anchorDate;
          }
        }

        // Same-day: enforce min duration
        if (isSameDay(startDate, endDate)) {
          newEndMinutes = clamp(
            newEndMinutes,
            anchorMinutes + minDurationMinutes,
            1440,
          );
        }
      } else if (cursorTimestamp < anchorTimestamp) {
        // Cursor is before anchor → effective top
        effectiveEdge = "top";
        endDate = anchorDate;
        newEndMinutes = anchorMinutes;
        startDate = targetDay;
        newStartMinutes = clamp(
          snappedMinutes,
          visibleStartMinutes,
          visibleEndMinutes,
        );

        // Cross-day edge case: cursor at minute 1440 on day right before anchor → treat as start-of-anchor-day
        if (!isSameDay(targetDay, anchorDate)) {
          const dayBeforeAnchor = new Date(anchorDate);
          dayBeforeAnchor.setDate(dayBeforeAnchor.getDate() - 1);
          dayBeforeAnchor.setHours(0, 0, 0, 0);

          if (isSameDay(targetDay, dayBeforeAnchor) && snappedMinutes >= 1440) {
            newStartMinutes = 0;
            startDate = anchorDate;
          }
        }

        // Same-day: enforce min duration
        if (isSameDay(startDate, endDate)) {
          newStartMinutes = clamp(
            newStartMinutes,
            0,
            anchorMinutes - minDurationMinutes,
          );
        }
      } else {
        // Cursor at anchor → keep minimum duration in original edge direction (no flip)
        effectiveEdge = resize.edge;
        if (resize.edge === "bottom") {
          startDate = anchorDate;
          newStartMinutes = anchorMinutes;
          endDate = anchorDate;
          newEndMinutes = anchorMinutes + minDurationMinutes;
        } else {
          endDate = anchorDate;
          newEndMinutes = anchorMinutes;
          startDate = anchorDate;
          newStartMinutes = anchorMinutes - minDurationMinutes;
        }
      }

      const currentStart = addMinutesToDate(startDate, newStartMinutes);
      const currentEnd = addMinutesToDate(endDate, newEndMinutes);

      resize.currentStart = currentStart;
      resize.currentEnd = currentEnd;

      setResizeState({
        eventId: resize.eventId,
        event: resize.event,
        originalStart: resize.event.start,
        originalEnd: resize.event.end,
        currentStart,
        currentEnd,
        edge: resize.edge,
        effectiveEdge,
        isResizing: true,
        currentEndDate: endDate,
        currentStartDate: startDate,
      });

      // Auto-scroll at top/bottom edges
      const cursorYInContainer = e.clientY - containerRect.top;
      const containerHeight = containerRect.height;

      if (cursorYInContainer < AUTO_SCROLL_ZONE_PX) {
        const dist = cursorYInContainer;
        autoScrollSpeedRef.current =
          -AUTO_SCROLL_MAX_SPEED * (1 - dist / AUTO_SCROLL_ZONE_PX);
        startAutoScrollLoop();
      } else if (cursorYInContainer > containerHeight - AUTO_SCROLL_ZONE_PX) {
        const dist = containerHeight - cursorYInContainer;
        autoScrollSpeedRef.current =
          AUTO_SCROLL_MAX_SPEED * (1 - dist / AUTO_SCROLL_ZONE_PX);
        startAutoScrollLoop();
      } else {
        cancelAutoScroll();
      }

      // Edge-of-view week navigation
      const cursorXInGrid = e.clientX - gridLeftEdge;
      const gridWidth = colWidth * visibleDays.length;

      if (cursorXInGrid < EDGE_ZONE_PX) {
        scheduleEdgeNav(-edgeNavigationDaysRef.current);
      } else if (cursorXInGrid > gridWidth - EDGE_ZONE_PX) {
        scheduleEdgeNav(edgeNavigationDaysRef.current);
      } else {
        cancelEdgeNav();
      }
    };

    handlePointerUpRef.current = (e: PointerEvent) => {
      const resize = resizeRef.current;
      if (!resize || e.pointerId !== resize.pointerId) return;

      cleanup();
      resizeRef.current = null;
      setResizeState(null);

      // Touch selects on release, after the resize, rather than on press
      if (resize.pointerType === "touch") {
        onEventClickRef.current?.(resize.event);
      }
      if (!resize.isResizing) return;
      suppressNextClick(resize.pointerType);

      // Commit from the handler, never from inside a state updater:
      // updaters run during render, and calling the parent's setState
      // there triggers "Cannot update a component while rendering".
      // A repeating event's generated occurrence isn't in `events`: commit
      // the copy the gesture started with
      const event =
        eventsRef.current.find((e) => e.id === resize.eventId) ?? resize.event;

      const MS_IN_24H = 24 * 60 * 60 * 1000;
      const isLongerThan24h =
        resize.currentEnd.getTime() - resize.currentStart.getTime() > MS_IN_24H;

      onEventChangeRef.current?.({
        ...event,
        start: resize.currentStart,
        end: resize.currentEnd,
        isAllDay: isLongerThan24h,
      });
    };

    // The browser took the pointer over (e.g. for a system gesture): drop
    // the resize without committing it
    handlePointerCancelRef.current = (e: PointerEvent) => {
      const resize = resizeRef.current;
      if (!resize || e.pointerId !== resize.pointerId) return;

      cleanup();
      resizeRef.current = null;
      setResizeState(null);
    };
  }, [
    scrollContainerRef,
    cleanup,
    cancelAutoScroll,
    startAutoScrollLoop,
    scheduleEdgeNav,
    cancelEdgeNav,
  ]);

  const beginResize = useCallback(
    (
      { clientY, pointerId, pointerType }: PointerGestureStart,
      event: CalendarEvent,
      edge: "top" | "bottom",
    ) => {
      // Mouse and pen select the event immediately
      if (pointerType !== "touch") onEventClickRef.current?.(event);

      const originalStartMinutes =
        event.start.getHours() * 60 + event.start.getMinutes();
      let originalEndMinutes =
        event.end.getHours() * 60 + event.end.getMinutes();

      const originalStartDate = startOfDay(event.start);
      let originalEndDate = startOfDay(event.end);

      // An end at the next midnight is minute 1440 of the day before, so the
      // resize starts within one day
      if (originalEndMinutes === 0 && !isSameDay(event.start, event.end)) {
        originalEndMinutes = 1440;
        originalEndDate = subDays(originalEndDate, 1);
      }

      resizeRef.current = {
        eventId: event.id,
        event,
        pointerId,
        pointerType,
        edge,
        startClientY: clientY,
        isResizing: false,
        originalStartMinutes,
        originalEndMinutes,
        originalStartDate,
        originalEndDate,
        currentStart: event.start,
        currentEnd: event.end,
      };

      setResizeState({
        eventId: event.id,
        event,
        originalStart: event.start,
        originalEnd: event.end,
        currentStart: event.start,
        currentEnd: event.end,
        edge,
        effectiveEdge: edge,
        isResizing: false,
        currentEndDate: originalEndDate,
        currentStartDate: originalStartDate,
      });

      if (handlePointerMoveRef.current) {
        window.addEventListener("pointermove", handlePointerMoveRef.current);
      }
      if (handlePointerUpRef.current) {
        window.addEventListener("pointerup", handlePointerUpRef.current);
      }
      if (handlePointerCancelRef.current) {
        window.addEventListener(
          "pointercancel",
          handlePointerCancelRef.current,
        );
      }
    },
    [],
  );

  const handleResizePointerDown = useCallback(
    (
      e: React.PointerEvent<HTMLElement>,
      event: CalendarEvent,
      edge: "top" | "bottom",
    ) => {
      if (!isPrimaryPress(e)) return;
      e.stopPropagation();
      startGesture(e, (start) => beginResize(start, event, edge));
    },
    [startGesture, beginResize],
  );

  useEffect(() => {
    return cleanup;
  }, [cleanup]);

  return { resizeState, handleResizePointerDown };
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { usePrefersReducedMotion } from "@/hooks/use-media-query";

interface UseHorizontalScrollOptions {
  containerRef: React.RefObject<HTMLDivElement | null>;
  dayColumnWidth: number;
  onNavigate: (daysDelta: number) => void;
  disabled?: boolean;
}

interface UseHorizontalScrollReturn {
  scrollOffset: number;
  slideOffset: number;
  isScrolling: boolean;
  isAnimating: boolean;
  triggerSlideAnimation: (daysDelta: number) => void;
}

const SCROLL_END_DEBOUNCE_MS = 150;
const SNAP_ANIMATION_MS = 200;

export function useHorizontalScroll({
  containerRef,
  dayColumnWidth,
  onNavigate,
  disabled,
}: UseHorizontalScrollOptions): UseHorizontalScrollReturn {
  const [scrollOffset, setScrollOffset] = useState(0);
  const [slideOffset, setSlideOffset] = useState(0);
  const [isScrolling, setIsScrolling] = useState(false);
  const [isAnimating, setIsAnimating] = useState(false);
  // Snaps and slides jump straight to their end instead of animating
  const prefersReducedMotion = usePrefersReducedMotion();

  const scrollEndTimer = useRef<ReturnType<typeof setTimeout>>(null);
  const accumulatedDelta = useRef(0);
  const onNavigateRef = useRef(onNavigate);
  useEffect(() => {
    onNavigateRef.current = onNavigate;
  }, [onNavigate]);

  const snapAndNavigate = useCallback(
    (offset: number) => {
      if (dayColumnWidth <= 0) return;

      const daysDelta = Math.round(offset / dayColumnWidth);

      if (prefersReducedMotion) {
        if (daysDelta !== 0) onNavigateRef.current(-daysDelta);
        setScrollOffset(0);
        setIsScrolling(false);
        accumulatedDelta.current = 0;
        return;
      }

      // If scroll distance < half a day-column width, snap back
      if (daysDelta === 0) {
        setIsAnimating(true);
        setScrollOffset(0);
        setTimeout(() => {
          setIsAnimating(false);
          setIsScrolling(false);
        }, SNAP_ANIMATION_MS);
        return;
      }

      // Snap to exact day boundary then navigate
      const targetOffset = daysDelta * dayColumnWidth;
      setIsAnimating(true);
      setScrollOffset(targetOffset);

      setTimeout(() => {
        onNavigateRef.current(-daysDelta);
        setScrollOffset(0);
        setIsAnimating(false);
        setIsScrolling(false);
        accumulatedDelta.current = 0;
      }, SNAP_ANIMATION_MS);
    },
    [dayColumnWidth, prefersReducedMotion],
  );

  // Programmatic slide animation for button/keyboard navigation
  // Uses slideOffset (not scrollOffset) so dynamicBuffer isn't affected
  // Does NOT call onNavigate — caller is responsible for having already changed the date
  const triggerSlideAnimation = useCallback(
    (daysDelta: number) => {
      if (dayColumnWidth <= 0 || isAnimating || isScrolling) return;
      if (prefersReducedMotion) return;

      // Start from the opposite direction to create slide effect
      const startOffset = daysDelta * dayColumnWidth;
      setSlideOffset(startOffset);

      // Force a reflow then animate to 0
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          setIsAnimating(true);
          setSlideOffset(0);
          setTimeout(() => {
            setIsAnimating(false);
          }, SNAP_ANIMATION_MS);
        });
      });
    },
    [dayColumnWidth, isAnimating, isScrolling, prefersReducedMotion],
  );

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const handleWheel = (e: WheelEvent) => {
      if (disabled) return;

      // Only handle horizontal-dominant scrolls
      if (Math.abs(e.deltaX) <= Math.abs(e.deltaY)) return;

      e.preventDefault();

      setIsScrolling(true);

      // Negate deltaX: scroll right (positive deltaX) = move calendar left = navigate forward
      accumulatedDelta.current += -e.deltaX;
      setScrollOffset(accumulatedDelta.current);

      // Reset debounce timer
      if (scrollEndTimer.current) {
        clearTimeout(scrollEndTimer.current);
      }

      scrollEndTimer.current = setTimeout(() => {
        snapAndNavigate(accumulatedDelta.current);
        accumulatedDelta.current = 0;
      }, SCROLL_END_DEBOUNCE_MS);
    };

    container.addEventListener("wheel", handleWheel, { passive: false });

    return () => {
      container.removeEventListener("wheel", handleWheel);
      if (scrollEndTimer.current) {
        clearTimeout(scrollEndTimer.current);
      }
    };
  }, [containerRef, snapAndNavigate, disabled]);

  return {
    scrollOffset,
    slideOffset,
    isScrolling,
    isAnimating,
    triggerSlideAnimation,
  };
}

import * as React from "react";

/** Matches when the viewer asked the system to minimize animation */
const REDUCED_MOTION_QUERY = "(prefers-reduced-motion: reduce)";

function getServerSnapshot(): boolean {
  return false;
}

/**
 * Subscribes to a CSS media query and returns whether it currently matches.
 *
 * Returns `false` during server rendering and hydration, then the live value.
 */
export function useMediaQuery(query: string): boolean {
  const subscribe = React.useCallback(
    (onChange: () => void) => {
      const mql = window.matchMedia(query);
      mql.addEventListener("change", onChange);
      return () => mql.removeEventListener("change", onChange);
    },
    [query],
  );

  const getSnapshot = React.useCallback(
    () => window.matchMedia(query).matches,
    [query],
  );

  return React.useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

/**
 * Whether the viewer prefers reduced motion. `false` during server
 * rendering and hydration, then the live value.
 */
export function usePrefersReducedMotion(): boolean {
  return useMediaQuery(REDUCED_MOTION_QUERY);
}
